CREATE TABLE parts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sku text NOT NULL UNIQUE,name text NOT NULL,brand text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',price numeric(14,2) NOT NULL CHECK(price>=0),reorder integer NOT NULL DEFAULT 0 CHECK(reorder>=0),bin text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,stock integer NOT NULL DEFAULT 0 CHECK(stock>=0),aliases jsonb NOT NULL DEFAULT '[]',fitments jsonb NOT NULL DEFAULT '[]',substitutes jsonb NOT NULL DEFAULT '[]',search_key text NOT NULL);
CREATE INDEX parts_search ON parts(search_key text_pattern_ops); CREATE INDEX parts_sku ON parts(sku); CREATE INDEX parts_fitment ON parts USING gin(fitments);
CREATE TABLE import_previews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor uuid NOT NULL REFERENCES users,rows jsonb NOT NULL,errors jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '1 hour',result jsonb);
CREATE TABLE postings(key text PRIMARY KEY,actor uuid NOT NULL REFERENCES users,operation text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL);
CREATE TABLE movements(id bigserial PRIMARY KEY,part_id uuid NOT NULL REFERENCES parts,qty integer NOT NULL CHECK(qty<>0),kind text NOT NULL,reason text NOT NULL,document_id text NOT NULL,actor uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE opening_parts(part_id uuid PRIMARY KEY REFERENCES parts);
CREATE INDEX movement_part ON movements(part_id,created_at);
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE);
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,phone text NOT NULL DEFAULT '');
CREATE TABLE purchases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES suppliers,status text NOT NULL CHECK(status IN ('draft','submitted','partial','received','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_lines(purchase_id uuid REFERENCES purchases,part_id uuid REFERENCES parts,qty integer NOT NULL CHECK(qty>0),received integer NOT NULL DEFAULT 0 CHECK(received>=0 AND received<=qty),cost numeric(14,2) NOT NULL CHECK(cost>=0),PRIMARY KEY(purchase_id,part_id));
CREATE TABLE receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_id uuid NOT NULL REFERENCES purchases,actor uuid REFERENCES users,lines jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),status text NOT NULL CHECK(status IN ('draft','posted')),actor uuid NOT NULL REFERENCES users,customer_id uuid REFERENCES customers,lines jsonb NOT NULL,subtotal numeric(14,2),tax numeric(14,2),total numeric(14,2),settings jsonb,created_at timestamptz NOT NULL DEFAULT now(),posted_at timestamptz);
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL UNIQUE REFERENCES sales,amount numeric(14,2) NOT NULL,method text NOT NULL CHECK(method IN ('cash','external')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sale_id uuid NOT NULL REFERENCES sales,actor uuid NOT NULL REFERENCES users,lines jsonb NOT NULL,reason text NOT NULL,refund_status text NOT NULL CHECK(refund_status IN ('pending','recorded')),created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION prevent_posted_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger rows are immutable'; END $$;
CREATE TRIGGER immutable_movements BEFORE UPDATE OR DELETE ON movements FOR EACH ROW EXECUTE FUNCTION prevent_posted_mutation();
